public sealed class CustomWebApplicationFactory : WebApplicationFactory<Program>
{
    protected override void ConfigureWebHost(IWebHostBuilder builder)
    {
        builder.UseEnvironment("Testing");

        builder.ConfigureAppConfiguration((ctx, config) =>
        {
            config.AddInMemoryCollection(new Dictionary<string, string?>
            {
                ["ConnectionStrings:Default"] = "Host=localhost;Database=orders_test;..."
            });
        });

        builder.ConfigureTestServices(services =>
        {
            services.AddSingleton<IEventPublisher, FakeEventPublisher>();
            // Optionally remove hosted services that poll in background
            services.RemoveAll(typeof(IHostedService));
        });
    }
}

public class OrderApiTests(CustomWebApplicationFactory factory) : IClassFixture<CustomWebApplicationFactory>
{
    [Fact]
    public async Task PostOrder_creates_order_and_outbox_row()
    {
        var client = factory.CreateClient();

        var response = await client.PostAsJsonAsync("/orders", new { customerId = "cust-1" });

        response.StatusCode.Should().Be(HttpStatusCode.Created);
        var body = await response.Content.ReadFromJsonAsync<CreateOrderResponse>();

        await using var scope = factory.Services.CreateAsyncScope();
        var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();

        var order = await db.Orders.FindAsync(body!.OrderId);
        order.Should().NotBeNull();

        var outbox = await db.OutboxMessages
            .FirstOrDefaultAsync(m => m.Payload.Contains(body.OrderId.ToString()));
        outbox.Should().NotBeNull();
        outbox!.ProcessedAt.Should().BeNull();
    }
}

